/* Reset and container styling */
* {
  margin: 0;
  padding: 0;
}

.container {
  width: 80%;
  margin: 0 auto;
  background-color: #f0f0f0;
}

/* Example: styling a box with default box-sizing */
.box-example {
  width: 150px;
  padding: 15px;
  border: 3px solid black;
  background-color: lightblue;
}

/* Similar: styling another element with same properties */
.box2 {
  width: 200px;
  padding: 20px;
  border: 5px solid #333;
  background-color: #f0f0f0;
}

/* Example of using pseudo-element to show dimensions */
.box::after {
  content: 'Width: 150px';
  display: block;
  text-align: center;
  margin-top: 10px;
  color: #333;
}

/* Example of applying border-box to an element */
.example-box {
  box-sizing: border-box;
  width: 150px;
  padding: 10px;
  border: 2px solid black;
}

/* This comment explains a CSS property */
.box-example {
  width: 100px;
}

/* Universal border-box reset */
* {
  box-sizing: border-box;
  box-sizing: inherit;
}

/* Example of adding explanatory text */
p {
  font-family: Arial, sans-serif;
  margin-top: 20px;
  color: #333;
}
